/**
 * Fleet & Commercial Partner job posting. Only owners of shops with
 * `partnerKind ∈ {dealership, fleet, gsa}` may post here — independent
 * shops rent bays via `/bays` instead. The server stamps a flat
 * commission override (default 15%, or 10% for GSA accounts when
 * `shop.commissionOverridePct` is configured) and a tier-priority
 * window: `urgent`=visible to all qualified mechanics immediately,
 * `high`=junior tiers wait 15m, `normal`=1h, `low`=4h. Senior+
 * mechanics always see partner-posted jobs immediately.
 * @summary Post a job from a Fleet or Dealership partner
 */
export const CreatePartnerJobBody = zod.object({
  "shopId": zod.number().describe('Partner shop posting the job. Must have partnerKind=dealership or fleet.'),
  "vehicleId": zod.number().describe('Vehicle from the partner\'s fleet (must be pre-registered via POST \/vehicles).'),
  "serviceSlug": zod.string().optional().describe('Preferred. Slug from \/tier-catalog. Server derives jobType + requiredTier.'),
  "jobType": zod.enum(['repair', 'diagnostic', 'maintenance', 'detailing']).optional().describe('Optional fallback when serviceSlug is not supplied.'),
  "description": zod.string(),
  "locationLat": zod.number().optional(),
  "locationLng": zod.number().optional(),
  "locationAddress": zod.string().optional(),
  "urgency": zod.enum(['low', 'normal', 'high', 'urgent']).optional().describe('Defaults to `normal`. Drives the tier-priority window for who sees the job when.'),
  "recurringGroupId": zod.string().optional().describe('Optional. Stamps a group id for bulk\/recurring fleet ops (e.g. monthly oil changes across 12 vehicles).')
})

